Write std::optional<int> parse_int(const std::string& s) that returns the value if parseable, else std::nullopt.
Solution
#include <optional>
#include <string>
#include <charconv>
std::optional<int> parse_int(const std::string& s) {
int value;
auto [ptr, ec] = std::from_chars(s.data(), s.data() + s.size(), value);
if (ec == std::errc{} && ptr == s.data() + s.size()) return value;
return std::nullopt;
}

Write constexpr int factorial(int n). Test by storing factorial(10) in a constexpr int.
Solution
constexpr int factorial(int n) {
return n <= 1 ? 1 : n * factorial(n - 1);
}
constexpr int x = factorial(10); // 3628800 — computed at compile time

